import { describe, expect, it } from "vitest";
// Generated by `uv run python -m roshni.ask.parity` from engine.check_prose.
import parity from "../../tests/fixtures/ask_parity.json";
import { checkProse, pyColumns } from "../src/prose";

describe("checkProse matches Python on every parity case", () => {
  for (const c of parity.prose) {
    it(JSON.stringify(c.text), () => {
      expect(checkProse(c.text, parity.facts, c.question)).toEqual(c.problems);
    });
  }
});

it("prints column lists the way Python repr does", () => {
  expect(pyColumns(["ibc", "share_12h_pct"])).toBe("['ibc', 'share_12h_pct']");
  expect(pyColumns([])).toBe("[]");
  expect(pyColumns(["it's"])).toBe(`["it's"]`);
});
